using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Application.Auditing;
using BARANG.Core.Application.Catalog;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Files;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Persistence;

public sealed class SupplierLifecycleAdministration(CoreDbContext db, ITransactionExecutor tx, ICompanyContext company, ICurrentActor actor, IAuditWriter audit, TimeProvider time) : ISupplierLifecycleAdministration
{
    private Guid Company => company.RequireCompanyId(); private Guid Actor => Guid.TryParse(actor.Actor.UserId, out Guid id) ? id : throw new InvalidOperationException("Authenticated actor required."); private DateTimeOffset Now => time.GetUtcNow();
    public Task<Result<SupplierLifecycleProfileView>> ProfileAsync(Guid supplier, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<SupplierLifecycleProfileView>(SupplierLifecycleErrors.NotFound); SupplierLifecycleProfile? p = await Profile(supplier, t); return Result.Success(View(p!)); }, ct);
    public Task<Result<SupplierLifecycleProfileView>> SetApprovalAsync(Guid supplier, SupplierApprovalCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierLifecycleProfile? p = await Profile(supplier, t); if (p is null) return Result.Failure<SupplierLifecycleProfileView>(SupplierLifecycleErrors.NotFound); Result r = p.SetApproval(command.Status, command.Version); if (r.IsFailure) return Result.Failure<SupplierLifecycleProfileView>(r.Error); if (command.QcLevelId is Guid qc) { if (!await db.LookupValues.AnyAsync(x => x.Id == qc && x.IsActive, t)) return Result.Failure<SupplierLifecycleProfileView>(SupplierLifecycleErrors.ReferenceNotFound); p.SetQuality(p.QualityScore, qc); } audit.Write(new("supplier.approval.changed", "supplier", supplier.ToString(), ChangeKind: AuditChangeKind.Modified)); return Result.Success(View(p)); }, ct);
    public Task<Result<SupplierLifecycleProfileView>> SetHoldAsync(Guid supplier, SupplierHoldCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierLifecycleProfile? p = await Profile(supplier, t); if (p is null) return Result.Failure<SupplierLifecycleProfileView>(SupplierLifecycleErrors.NotFound); Result r = p.SetHold(command.Held, command.Reason, command.Notes, Actor, Now, command.Version); if (r.IsFailure) return Result.Failure<SupplierLifecycleProfileView>(r.Error); audit.Write(new(command.Held ? "supplier.hold.created" : "supplier.hold.released", "supplier", supplier.ToString(), ChangeKind: AuditChangeKind.Modified)); return Result.Success(View(p)); }, ct);
    public Task<Result<SupplierEvaluationView>> CreateEvaluationAsync(Guid supplier, SupplierEvaluationCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.NotFound); Result<SupplierEvaluation> created = SupplierEvaluation.Create(Company, supplier, command.EvaluationDate, command.PeriodStart, command.PeriodEnd, Actor, command.Notes, Now); if (created.IsFailure) return Result.Failure<SupplierEvaluationView>(created.Error); List<SupplierEvaluationCriterionCommand> submitted = command.Criteria.DistinctBy(x => x.CriterionId).ToList(); if (submitted.Count == 0 || submitted.Any(x => x.Score is < 0 or > 100)) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.InvalidData); var validCriteria = await (from value in db.LookupValues join type in db.LookupTypes on value.LookupTypeId equals type.Id where type.Code == "supplier.evaluation.criterion" && value.IsActive && submitted.Select(x => x.CriterionId).Contains(value.Id) select value.Id).ToListAsync(t); if (validCriteria.Count != submitted.Count) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.ReferenceNotFound); decimal score = submitted.Average(x => x.Score); string result = score >= 70m ? "Approved" : "Rejected"; Result update = created.Value.Update(score, result, command.Notes, 1); if (update.IsFailure) return Result.Failure<SupplierEvaluationView>(update.Error); db.SupplierEvaluations.Add(created.Value); List<SupplierEvaluationCriterion> criteria = []; foreach (SupplierEvaluationCriterionCommand item in submitted) { Result<SupplierEvaluationCriterion> row = SupplierEvaluationCriterion.Create(Company, created.Value.Id, item.CriterionId, item.Score, item.Comment); if (row.IsFailure) return Result.Failure<SupplierEvaluationView>(row.Error); criteria.Add(row.Value); } db.SupplierEvaluationCriteria.AddRange(criteria); SupplierLifecycleProfile? profile = await Profile(supplier, t); if (profile is not null) profile.SetQuality(score, profile.QcLevelId); audit.Write(new("supplier.evaluation.created", "supplier_evaluation", created.Value.Id.ToString(), ChangeKind: AuditChangeKind.Added)); return Result.Success(new SupplierEvaluationView(created.Value, criteria)); }, ct);
    public Task<Result<IReadOnlyList<SupplierEvaluationView>>> EvaluationsAsync(Guid supplier, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<IReadOnlyList<SupplierEvaluationView>>(SupplierLifecycleErrors.NotFound); List<SupplierEvaluation> values = await db.SupplierEvaluations.AsNoTracking().Where(x => x.SupplierId == supplier).OrderByDescending(x => x.EvaluationDate).ToListAsync(t); Dictionary<Guid, List<SupplierEvaluationCriterion>> criteria = await db.SupplierEvaluationCriteria.AsNoTracking().Where(x => values.Select(v => v.Id).Contains(x.EvaluationId)).GroupBy(x => x.EvaluationId).ToDictionaryAsync(x => x.Key, x => x.ToList(), t); return Result.Success<IReadOnlyList<SupplierEvaluationView>>(values.Select(x => new SupplierEvaluationView(x, criteria.GetValueOrDefault(x.Id) ?? [])).ToArray()); }, ct);
    public Task<Result<SupplierEvaluationView>> UpdateEvaluationAsync(Guid supplier, Guid id, SupplierEvaluationCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierEvaluation? evaluation = await db.SupplierEvaluations.SingleOrDefaultAsync(x => x.Id == id && x.SupplierId == supplier, t); if (evaluation is null) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.NotFound); List<SupplierEvaluationCriterionCommand> submitted = command.Criteria.DistinctBy(x => x.CriterionId).ToList(); if (submitted.Count == 0 || submitted.Any(x => x.Score is < 0 or > 100)) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.InvalidData); var valid = await (from value in db.LookupValues join type in db.LookupTypes on value.LookupTypeId equals type.Id where type.Code == "supplier.evaluation.criterion" && value.IsActive && submitted.Select(x => x.CriterionId).Contains(value.Id) select value.Id).ToListAsync(t); if (valid.Count != submitted.Count) return Result.Failure<SupplierEvaluationView>(SupplierLifecycleErrors.ReferenceNotFound); Result dates = evaluation.UpdateDates(command.EvaluationDate, command.PeriodStart, command.PeriodEnd, command.Version); if (dates.IsFailure) return Result.Failure<SupplierEvaluationView>(dates.Error); decimal score = submitted.Average(x => x.Score); Result updated = evaluation.Update(score, score >= 70m ? "Approved" : "Rejected", command.Notes, command.Version + 1); if (updated.IsFailure) return Result.Failure<SupplierEvaluationView>(updated.Error); List<SupplierEvaluationCriterion> old = await db.SupplierEvaluationCriteria.Where(x => x.EvaluationId == id).ToListAsync(t); db.SupplierEvaluationCriteria.RemoveRange(old); List<SupplierEvaluationCriterion> rows = []; foreach (SupplierEvaluationCriterionCommand item in submitted) { Result<SupplierEvaluationCriterion> row = SupplierEvaluationCriterion.Create(Company, id, item.CriterionId, item.Score, item.Comment); if (row.IsFailure) return Result.Failure<SupplierEvaluationView>(row.Error); rows.Add(row.Value); } db.SupplierEvaluationCriteria.AddRange(rows); audit.Write(new("supplier.evaluation.updated", "supplier_evaluation", id.ToString(), ChangeKind: AuditChangeKind.Modified)); return Result.Success(new SupplierEvaluationView(evaluation, rows)); }, ct);
    public Task<Result<IReadOnlyList<SupplierQualityIncident>>> IncidentsAsync(Guid supplier, CancellationToken ct) => tx.ExecuteAsync(async t => !await db.Suppliers.AnyAsync(x => x.Id == supplier, t) ? Result.Failure<IReadOnlyList<SupplierQualityIncident>>(SupplierLifecycleErrors.NotFound) : Result.Success<IReadOnlyList<SupplierQualityIncident>>(await db.SupplierQualityIncidents.AsNoTracking().Where(x => x.SupplierId == supplier).OrderByDescending(x => x.IncidentDate).ToListAsync(t)), ct);
    public Task<Result<SupplierQualityIncident>> CreateIncidentAsync(Guid supplier, SupplierQualityIncidentCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<SupplierQualityIncident>(SupplierLifecycleErrors.NotFound); Result<SupplierQualityIncident> x = SupplierQualityIncident.Create(Company, supplier, command.IncidentType, command.IncidentDate, command.Quantity, command.Description, Actor, Now); if (x.IsFailure) return x; db.SupplierQualityIncidents.Add(x.Value); audit.Write(new("supplier.quality.incident.created", "supplier_quality_incident", x.Value.Id.ToString(), ChangeKind: AuditChangeKind.Added)); return x; }, ct);
    public Task<Result<SupplierQualityIncident>> ResolveIncidentAsync(Guid supplier, Guid id, SupplierQualityResolveCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierQualityIncident? x = await db.SupplierQualityIncidents.SingleOrDefaultAsync(v => v.SupplierId == supplier && v.Id == id, t); if (x is null) return Result.Failure<SupplierQualityIncident>(SupplierLifecycleErrors.NotFound); Result r = x.Resolve(command.CorrectiveAction, command.ResolvedDate, command.Version); return r.IsFailure ? Result.Failure<SupplierQualityIncident>(r.Error) : Result.Success(x); }, ct);
    public Task<Result<SupplierQualityIncident>> UpdateIncidentAsync(Guid supplier, Guid id, SupplierQualityIncidentCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierQualityIncident? x = await db.SupplierQualityIncidents.SingleOrDefaultAsync(v => v.SupplierId == supplier && v.Id == id, t); if (x is null) return Result.Failure<SupplierQualityIncident>(SupplierLifecycleErrors.NotFound); Result r = x.Update(command.IncidentType, command.IncidentDate, command.Quantity, command.Description, command.Version); return r.IsFailure ? Result.Failure<SupplierQualityIncident>(r.Error) : Result.Success(x); }, ct);
    public Task<Result> SetIncidentActiveAsync(Guid supplier, Guid id, bool active, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierQualityIncident? x = await db.SupplierQualityIncidents.SingleOrDefaultAsync(v => v.SupplierId == supplier && v.Id == id, t); if (x is null) return Result.Failure(SupplierLifecycleErrors.NotFound); return x.SetActive(active, version); }, ct);
    public Task<Result<SupplierContractView>> SaveContractAsync(Guid supplier, Guid? id, SupplierContractCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t) || !await db.LookupValues.AnyAsync(x => x.Id == command.ContractTypeId, t)) return Result.Failure<SupplierContractView>(SupplierLifecycleErrors.ReferenceNotFound); SupplierContract? x = id is null ? null : await db.SupplierContracts.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is null) { Result<SupplierContract> created = SupplierContract.Create(Company, supplier, command.ContractNumber, command.ContractTypeId, command.StartDate, command.EndDate, command.Description, command.ContractValue, command.CurrencyCode); if (created.IsFailure) return Result.Failure<SupplierContractView>(created.Error); if (await db.SupplierContracts.AnyAsync(v => v.ContractNumber == created.Value.ContractNumber, t)) return Result.Failure<SupplierContractView>(SupplierLifecycleErrors.Duplicate); x = created.Value; db.SupplierContracts.Add(x); } else { Result r = x.Update(command.EndDate, command.Status, command.Description, command.ContractValue, command.Version); if (r.IsFailure) return Result.Failure<SupplierContractView>(r.Error); } audit.Write(new("supplier.contract.saved", "supplier_contract", x.Id.ToString(), ChangeKind: id is null ? AuditChangeKind.Added : AuditChangeKind.Modified)); return Result.Success(ContractView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result<SupplierContractView>> AttachContractFileAsync(Guid supplier, Guid id, SupplierContractFileCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierContract? x = await db.SupplierContracts.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); bool fileOk = await db.StoredFiles.AnyAsync(v => v.Id == command.FileId, t); bool versionOk = command.FileVersionId is null || await db.FileVersions.AnyAsync(v => v.Id == command.FileVersionId && v.FileId == command.FileId && !v.IsArchived, t); if (x is null || !fileOk || !versionOk) return Result.Failure<SupplierContractView>(SupplierLifecycleErrors.NotFound); Result linked = x.Attach(command.FileId, command.FileVersionId, command.Version); if (linked.IsFailure) return Result.Failure<SupplierContractView>(linked.Error); if (!await db.FileLinks.AnyAsync(v => v.FileId == command.FileId && v.EntityType == FileLinkEntityType.SupplierContract && v.EntityId == id && v.IsActive, t)) db.FileLinks.Add(FileLink.Create(Company, command.FileId, command.FileVersionId, FileLinkEntityType.SupplierContract, id, FileLinkPurpose.Attachment, Actor, Now)); audit.Write(new("supplier.contract.file.attached", "supplier_contract", id.ToString(), ChangeKind: AuditChangeKind.Modified)); return Result.Success(ContractView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result<IReadOnlyList<SupplierContractView>>> ContractsAsync(Guid supplier, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<IReadOnlyList<SupplierContractView>>(SupplierLifecycleErrors.NotFound); List<SupplierContract> values = await db.SupplierContracts.AsNoTracking().Where(x => x.SupplierId == supplier).OrderByDescending(x => x.StartDate).ToListAsync(t); return Result.Success<IReadOnlyList<SupplierContractView>>(values.Select(x => ContractView(x, DateOnly.FromDateTime(Now.DateTime))).ToArray()); }, ct);
    public Task<Result> DeleteContractAsync(Guid supplier, Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierContract? x = await db.SupplierContracts.SingleOrDefaultAsync(v => v.SupplierId == supplier && v.Id == id, t); if (x is null) return Result.Failure(SupplierLifecycleErrors.NotFound); if (x.Version != version || x.Status != "Draft") return Result.Failure(x.Version != version ? SupplierLifecycleErrors.Concurrency : SupplierLifecycleErrors.InvalidTransition); db.SupplierContracts.Remove(x); return Result.Success(); }, ct);
    public Task<Result<SupplierDocumentView>> SaveDocumentAsync(Guid supplier, Guid? id, SupplierDocumentCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t) || !await db.LookupValues.AnyAsync(x => x.Id == command.DocumentTypeId, t)) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.ReferenceNotFound); SupplierDocument? x = id is null ? null : await db.SupplierDocuments.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is not null) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.InvalidTransition); Result<SupplierDocument> created = SupplierDocument.Create(Company, supplier, command.DocumentTypeId, command.ContractId, command.DocumentNumber, command.IssueDate, command.ExpiryDate, command.Description, command.IssuingAuthority); if (created.IsFailure) return Result.Failure<SupplierDocumentView>(created.Error); x = created.Value; db.SupplierDocuments.Add(x); audit.Write(new("supplier.document.created", "supplier_document", x.Id.ToString(), ChangeKind: AuditChangeKind.Added)); return Result.Success(DocumentView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result<IReadOnlyList<SupplierDocumentView>>> DocumentsAsync(Guid supplier, CancellationToken ct) => tx.ExecuteAsync(async t => { if (!await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) return Result.Failure<IReadOnlyList<SupplierDocumentView>>(SupplierLifecycleErrors.NotFound); List<SupplierDocument> values = await db.SupplierDocuments.AsNoTracking().Where(x => x.SupplierId == supplier).OrderByDescending(x => x.ExpiryDate).ToListAsync(t); return Result.Success<IReadOnlyList<SupplierDocumentView>>(values.Select(x => DocumentView(x, DateOnly.FromDateTime(Now.DateTime))).ToArray()); }, ct);
    public Task<Result<SupplierDocumentView>> AttachDocumentFileAsync(Guid supplier, Guid id, SupplierFileCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierDocument? x = await db.SupplierDocuments.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is null || !await db.StoredFiles.AnyAsync(v => v.Id == command.FileId, t) || command.FileVersionId is not null && !await db.FileVersions.AnyAsync(v => v.Id == command.FileVersionId && v.FileId == command.FileId && !v.IsArchived, t)) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.NotFound); Result r = x.Attach(command.FileId, command.FileVersionId, command.Version); if (r.IsFailure) return Result.Failure<SupplierDocumentView>(r.Error); if (!await db.FileLinks.AnyAsync(v => v.FileId == command.FileId && v.EntityType == FileLinkEntityType.SupplierDocument && v.EntityId == id && v.IsActive, t)) db.FileLinks.Add(FileLink.Create(Company, command.FileId, command.FileVersionId, FileLinkEntityType.SupplierDocument, id, FileLinkPurpose.Attachment, Actor, Now)); return Result.Success(DocumentView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result<SupplierDocumentView>> UpdateDocumentAsync(Guid supplier, Guid id, SupplierDocumentCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierDocument? x = await db.SupplierDocuments.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is null || !await db.LookupValues.AnyAsync(v => v.Id == command.DocumentTypeId && v.IsActive, t)) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.ReferenceNotFound); if (command.ContractId is not null && !await db.SupplierContracts.AnyAsync(v => v.Id == command.ContractId && v.SupplierId == supplier, t)) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.ReferenceNotFound); Result r = x.Update(command.DocumentTypeId, command.ContractId, command.DocumentNumber, command.IssueDate, command.ExpiryDate, command.Description, command.IssuingAuthority, command.Version); return r.IsFailure ? Result.Failure<SupplierDocumentView>(r.Error) : Result.Success(DocumentView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result<SupplierDocumentView>> SetDocumentStatusAsync(Guid supplier, Guid id, SupplierDocumentStatusCommand command, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierDocument? x = await db.SupplierDocuments.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is null) return Result.Failure<SupplierDocumentView>(SupplierLifecycleErrors.NotFound); Result r = x.SetStatus(command.Status, command.Version); return r.IsFailure ? Result.Failure<SupplierDocumentView>(r.Error) : Result.Success(DocumentView(x, DateOnly.FromDateTime(Now.DateTime))); }, ct);
    public Task<Result> DeleteDocumentAsync(Guid supplier, Guid id, long version, CancellationToken ct) => tx.ExecuteAsync(async t => { SupplierDocument? x = await db.SupplierDocuments.SingleOrDefaultAsync(v => v.Id == id && v.SupplierId == supplier, t); if (x is null) return Result.Failure(SupplierLifecycleErrors.NotFound); if (x.Version != version || x.FileId is not null) return Result.Failure(x.Version != version ? SupplierLifecycleErrors.Concurrency : SupplierLifecycleErrors.InvalidTransition); db.SupplierDocuments.Remove(x); return Result.Success(); }, ct);
    private async Task<SupplierLifecycleProfile?> Profile(Guid supplier, CancellationToken t) { SupplierLifecycleProfile? p = await db.SupplierLifecycleProfiles.SingleOrDefaultAsync(x => x.SupplierId == supplier, t); if (p is null && await db.Suppliers.AnyAsync(x => x.Id == supplier, t)) { p = SupplierLifecycleProfile.Create(Company, supplier); db.SupplierLifecycleProfiles.Add(p); } return p; }
    private static SupplierLifecycleProfileView View(SupplierLifecycleProfile p) => new(p.SupplierId, p.ApprovalStatus, p.QualityScore, p.QcLevelId, p.HoldReason, p.HeldAtUtc, p.Version);
    private static SupplierContractView ContractView(SupplierContract x, DateOnly today) => new(x, x.EndDate < today, x.EndDate is not null && x.EndDate >= today && x.EndDate <= today.AddDays(30));
    private static SupplierDocumentView DocumentView(SupplierDocument x, DateOnly today) => new(x, x.ExpiryDate < today, x.ExpiryDate is not null && x.ExpiryDate >= today && x.ExpiryDate <= today.AddDays(30));
}
